287→                        <p className="mt-0.5">Send prompts and review tool calls in real time</p>
288→                      </div>
289→                    </div>
290→                    <div className="flex items-start gap-2 rounded-lg border p-3">
291→                      <ListTodo className="mt-0.5 size-3.5 shrink-0 text-primary" />
292→                      <div>
293→                        <p className="font-medium text-foreground/80">Tasks</p>
294→                        <p className="mt-0.5">Track work with a kanban board and delegate to agents</p>
295→                      </div>
296→                    </div>
297→                  </div>
298→                </div>
299→              ),
300→            }}
301→          />
