303→        {!atBottom && displayItems.length > 0 && !showRaw && !loading && (
304→          <button
305→            onClick={() => virtuosoRef.current?.scrollToIndex({ index: displayItems.length - 1, behavior: "smooth" })}
306→            className="absolute bottom-3 right-3 flex items-center gap-1 rounded-full border bg-background/90 px-3 py-1.5 text-xs text-muted-foreground shadow-md backdrop-blur transition-colors hover:text-foreground"
307→          >
308→            <ArrowDown className="size-3" />
309→            Latest
310→          </button>
311→        )}
312→      </div>
313→
314→      {isArchived && messages.length > 0 ? (
315→        <div className="border-t px-4 py-2 text-center text-xs text-muted-foreground">
316→          This session has ended
317→        </div>
318→      ) : (
319→        <div className="border-t">
320→          {/* Prompt templates — spawn mode only */}
321→          {!isActive && (
322→            <div className="flex flex-wrap gap-1.5 px-2 pt-2 md:px-4">
323→              {PROMPT_TEMPLATES.map((t) => (
324→                <button
325→                  key={t.label}
326→                  type="button"
327→                  onClick={() => { setInput(t.prompt); inputRef.current?.focus(); }}
328→                  className="rounded-full border px-2.5 py-1 text-[11px] text-muted-foreground transition-colors hover:border-foreground/30 hover:text-foreground"
329→                >
330→                  {t.label}
331→                </button>
332→              ))}
333→              <button
334→                type="button"
335→                onClick={() => setShowSystemPrompt((v) => !v)}
336→                className="ml-auto flex items-center gap-1 rounded-full border px-2.5 py-1 text-[11px] text-muted-foreground transition-colors hover:border-foreground/30 hover:text-foreground"
337→              >
338→                {showSystemPrompt ? <ChevronDown className="size-3" /> : <ChevronRight className="size-3" />}
339→                System prompt
340→              </button>
341→            </div>
342→          )}
343→
344→          {/* System prompt textarea — spawn mode only */}
345→          {!isActive && showSystemPrompt && (
346→            <div className="px-2 pt-1.5 md:px-4">
347→              <textarea
348→                value={systemPrompt}
349→                onChange={(e) => setSystemPrompt(e.target.value)}
350→                placeholder="Optional system instructions (e.g. 'You are a code reviewer. Focus on security issues.')"
351→                rows={3}
352→                className="w-full resize-none rounded-md border bg-background px-3 py-2 text-xs outline-none focus:ring-2 focus:ring-ring"
353→              />
354→            </div>
355→          )}
356→
357→          <form
358→            onSubmit={handleSubmit}
359→            className="relative flex gap-2 px-2 py-2 md:px-4 md:py-3"
360→          >
361→            {showSlashMenu && (
362→              <SlashCommandMenu
363→                query={slashQuery}
364→                highlightedIndex={slashHighlight}
365→                onSelect={handleCommandSelect}
366→                onHighlight={setSlashHighlight}
367→              />
368→            )}
369→            <input
370→              ref={inputRef}
371→              type="text"
372→              value={input}
373→              onChange={handleInputChange}
374→              onKeyDown={handleKeyDown}
375→              placeholder={isActive ? "Send a follow-up..." : "Enter a prompt to spawn agent..."}
376→              className="flex-1 rounded-md border bg-background px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-ring"
377→            />
378→            <Button type="submit" disabled={!connected || !input.trim()}>
379→              {isActive ? "Send" : "Spawn"}
380→            </Button>
381→          </form>
382→        </div>
383→      )}
384→    </div>
385→  );
386→}
387→
388→const PROMPT_TEMPLATES = [
389→  { label: "Review code", prompt: "Review the recent changes and provide feedback on code quality, bugs, and improvements." },
390→  { label: "Write tests", prompt: "Write comprehensive tests for the recent changes." },
391→  { label: "Fix bug", prompt: "" },
392→  { label: "Refactor", prompt: "Refactor the codebase for better readability and maintainability." },
393→  { label: "Explain", prompt: "" },
394→];
395→
396→/** Badge color per Claude NDJSON message type. */
397→const TYPE_COLORS: Record<string, string> = {
398→  system: "text-yellow-500",
399→  assistant: "text-blue-400",
400→  result: "text-green-500",
401→  control_request: "text-orange-400",
402→  keep_alive: "text-muted-foreground",
403→};
404→
405→function RawMessage({ message, index }: { message: ClaudeMessage; index: number }) {
406→  const [expanded, setExpanded] = useState(false);
407→  const subtype = (message as { subtype?: string }).subtype;
408→  const typeLabel = subtype ? `${message.type}/${subtype}` : message.type;
409→  const colorClass = TYPE_COLORS[message.type] ?? "text-muted-foreground";
410→
411→  return (
412→    <div className="font-mono text-[11px] leading-relaxed">
413→      <button
414→        onClick={() => setExpanded((v) => !v)}
415→        className="flex w-full items-center gap-2 rounded px-2 py-1 text-left hover:bg-muted/50 transition-colors"
416→      >
417→        <span className="text-muted-foreground w-6 shrink-0 text-right">{index}</span>
418→        <span className={colorClass}>{typeLabel}</span>
419→        <span className="text-muted-foreground">{expanded ? "▼" : "▶"}</span>
420→      </button>
421→      {expanded && (
422→        <pre className="ml-10 overflow-x-auto rounded bg-muted/30 p-2 text-[10px] text-muted-foreground whitespace-pre-wrap break-all">
423→          {JSON.stringify(message, null, 2)}
424→        </pre>
425→      )}
426→    </div>
427→  );
428→}
